import{_ as a,o,c as r,l as s,t as n,N as t}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"docker-image-rm | x-cmd man (docker man1) | Remove one or more images","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-image-rm - Remove one or more images","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-image-rm | x-cmd man (docker man1) | Remove one or more images"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-image-rm - Remove one or more images"}]]},"headers":[],"params":{"isMan":true,"man":"docker-image-rm","category":"docker man1","desc":"Remove one or more images"},"relativePath":"docker/man1/docker-image-rm.md","filePath":"docker/man1/docker-image-rm.md"}'),i={name:"docker/man1/docker-image-rm.md"},m={class:"visually-hidden"},d=t('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-image-rm - Remove one or more images</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker image rm [OPTIONS] IMAGE [IMAGE...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Removes (and un-tags) one or more images from the host node. If an image has multiple tags, using this command with the tag as a parameter only removes the tag. If the tag is the only one for the image, both the image and the tag are removed.</p><p>This does not remove images from a registry. You cannot remove an image of a running container unless you use the <strong>-f</strong> option. To see all images on a host use the <strong>docker image ls</strong> command.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="removing-an-image" tabindex="-1">Removing an image <a class="header-anchor" href="#removing-an-image" aria-label="Permalink to &quot;Removing an image&quot;">​</a></h2><p>Here is an example of removing an image:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fedora/httpd</span></span></code></pre></div><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-f</strong>, <strong>--force</strong>[=false] Force removal of the image</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for rm</p><p><strong>--no-prune</strong>[=false] Do not delete untagged parents</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-image(1)</strong></p>',17);function h(e,l,g,c,p,k){return o(),r("div",null,[s("h1",m,n(e.$params.man),1),d])}const _=a(i,[["render",h]]);export{f as __pageData,_ as default};
